export declare class Util {
    /**
     * Extracts the name of a variable returned by the passed function.
     * e.g. getVariableName(() => this.model.myVariable) will return "myVariable"
     * getVariableName(function() { return this.model.myVariable; }) will return "myVariable"
     * @param func A simple function that returns a variable from a model.
     * @param addLocalIdentifier Whether to add a predefined local identifier prefix. e.g. "_myVariable".
     * Defined by BindingModel.LOCAL_MODEL_VALUE_IDENTIFIER.
     * @returns The extracted variable name.
     */
    static getVariableName<TResult>(func: () => TResult, addLocalIdentifier?: boolean): string;
}
